-- Optional source-specific routes preserve legacy topic search behavior.
ALTER TABLE "glean_topic" ADD COLUMN "search_routes" jsonb NOT NULL DEFAULT '[]'::jsonb;
-- Append-only provenance; observation association intentionally has no physical FK.
CREATE TABLE "glean_search_hit" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "observation_id" bigint NOT NULL, "run_id" bigint NOT NULL, "query_id" character varying NOT NULL, "query_version" character varying NOT NULL, "plan_version" character varying NOT NULL, "source" character varying NOT NULL, "query_text" text NOT NULL, "mode" character varying NOT NULL, "discovered_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "created_by" bigint NULL, "updated_by" bigint NULL, PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "gleansearchhit_observation_id_run_id_query_id_query_version" ON "glean_search_hit" ("observation_id", "run_id", "query_id", "query_version");
CREATE INDEX "gleansearchhit_run_id" ON "glean_search_hit" ("run_id");
